def pluck(arr):
    smallest_even = float('inf')
    smallest_index = -1

    for index, value in enumerate(arr):
        if value % 2 == 0:
            if value < smallest_even or (value == smallest_even and smallest_index == -1):
                smallest_even = value
                smallest_index = index

    if smallest_index == -1:
        return []

    return [smallest_even, smallest_index]
